import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Distanza Terra-Sole","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/i_trigonometria/ie/iecb.md","filePath":"lezioni/i_trigonometria/ie/iecb.md"}`),a={name:`lezioni/i_trigonometria/ie/iecb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="distanza-terra-sole" tabindex="-1">Distanza Terra-Sole <a class="header-anchor" href="#distanza-terra-sole" aria-label="Permalink to “Distanza Terra-Sole”">​</a></h1><p>Data la grande distanza Terra-Sole non possiamo prendere come base il raggio terrestre per fare lo stesso ragionamento fatto nella pagina precedente perché l&#39;angolo da misurare sarebbe troppo esiguo: possiamo però prendere come base la distanza Terra-Luna. Date le grandi distanze possiamo considerare la Terra, la Luna ed il Sole come puntiformi; la figura naturalmente non corrisponde alla realtà: dovrei disegnare un triangolo sottilissimo e lunghissimo.</p><p>Consideriamo un triangolo rettangolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mi>S</mi><mi>T</mi></mrow><annotation encoding="application/x-tex">LST</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> con vertici la Luna, il Sole e la Terra: per fare questo dobbiamo prendere il giorno in cui la Luna è esattamente al primo quarto (sul calendario quando la Luna sembra uno spicchio di arancia con la gobba verso destra) oppure anche all&#39;ultimo quarto (gobba verso sinistra): in questo modo la Luna presenterà la faccia illuminata al Sole e noi, vedendo solo mezza Luna illuminata, saremo perpendicolari ai raggi che illuminano la Luna stessa.</p><p>Misuriamo (al tramonto) direttamente l&#39;angolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mi>T</mi><mi>S</mi><mo>=</mo><mi>α</mi></mrow><annotation encoding="application/x-tex">LTS = \\alpha</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span></p><p>Conosciamo quindi anche l&#39;angolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>S</mi><mi>L</mi><mo>=</mo><msup><mn>90</mn><mo>∘</mo></msup><mo>−</mo><mi>α</mi></mrow><annotation encoding="application/x-tex">TSL = 90^\\circ - \\alpha</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7574em;vertical-align:-0.0833em;"></span><span class="mord">9</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span></p><p>Possiamo applicare il teorema dei seni:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mfrac><mrow><mi>T</mi><mi>S</mi></mrow><mrow><mi>sin</mi><mo>⁡</mo><msup><mn>90</mn><mo>∘</mo></msup></mrow></mfrac><mo>=</mo><mfrac><mrow><mi>T</mi><mi>L</mi></mrow><mrow><mi>sin</mi><mo>⁡</mo><mo stretchy="false">(</mo><msup><mn>90</mn><mo>∘</mo></msup><mo>−</mo><mi>α</mi><mo stretchy="false">)</mo></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\frac{TS}{\\sin 90^\\circ} = \\frac{TL}{\\sin (90^\\circ - \\alpha)}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord" style="color:red;"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;"><span class="mop" style="color:red;"><span style="color:red;">s</span><span style="color:red;">i</span><span style="color:red;">n</span></span><span class="mspace" style="color:red;margin-right:0.1667em;"></span><span class="mord" style="color:red;">9</span><span class="mord" style="color:red;"><span class="mord" style="color:red;">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6001em;"><span style="top:-2.989em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight" style="color:red;"><span class="mbin mtight" style="color:red;">∘</span></span></span></span></span></span></span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="color:red;border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;"><span class="mord mathnormal" style="margin-right:0.1389em;color:red;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;color:red;">S</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.2963em;vertical-align:-0.936em;"></span><span class="mord" style="color:red;"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;"><span class="mop" style="color:red;"><span style="color:red;">s</span><span style="color:red;">i</span><span style="color:red;">n</span></span><span class="mopen" style="color:red;">(</span><span class="mord" style="color:red;">9</span><span class="mord" style="color:red;"><span class="mord" style="color:red;">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6001em;"><span style="top:-2.989em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight" style="color:red;"><span class="mbin mtight" style="color:red;">∘</span></span></span></span></span></span></span></span><span class="mspace" style="color:red;margin-right:0.2222em;"></span><span class="mbin" style="color:red;">−</span><span class="mspace" style="color:red;margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;color:red;">α</span><span class="mclose" style="color:red;">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="color:red;border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;"><span class="mord mathnormal" style="margin-right:0.1389em;color:red;">T</span><span class="mord mathnormal" style="color:red;">L</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>essendo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>sin</mi><mo>⁡</mo><msup><mn>90</mn><mo>∘</mo></msup><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\sin 90^\\circ = 1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6741em;"></span><span class="mop">sin</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">9</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>, considerando inoltre la relazione sugli angoli complementari avremo quindi per la distanza Terra-Sole:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mi>T</mi><mi>S</mi><mo>=</mo><mfrac><mrow><mi>T</mi><mi>L</mi></mrow><mrow><mi>cos</mi><mo>⁡</mo><mi>α</mi></mrow></mfrac></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{TS = \\frac{TL}{\\cos \\alpha}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;color:red;">T</span><span class="mord mathnormal" style="margin-right:0.0576em;color:red;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord" style="color:red;"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;"><span class="mop" style="color:red;"><span style="color:red;">c</span><span style="color:red;">o</span><span style="color:red;">s</span></span><span class="mspace" style="color:red;margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;color:red;">α</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="color:red;border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="color:red;"><span class="mord mathnormal" style="margin-right:0.1389em;color:red;">T</span><span class="mord mathnormal" style="color:red;">L</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><blockquote><p>Avrei potuto usare anche la formula inversa della relazione fra triangoli rettangoli: <strong>l&#39;ipotenusa è uguale ad un cateto fratto il coseno dell&#39;angolo adiacente al cateto considerato</strong>, ma siccome abbiamo sinora usato il teorema dei seni...</p></blockquote>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};